                    if (0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen
                            and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            minr = min(x for x, y in cells)
            minc = min(y for x, y in cells)
            shape = frozenset((x - minr, y - minc) for x, y in cells)
            components.append((color, cells, shape))

    shape_colors = {}
    for color, cells, shape in components:
        shape_colors.setdefault(shape, set()).add(color)

    out = [row[:] for row in grid]
    for color, cells, shape in components:
        if color == 1:
            others = shape_colors[shape] - {1}
            if others:
                replacement = min(others)
                for r, c in cells:
                    out[r][c] = replacement
    return out
